"""Offline audit of observation dates, specifications, and observation forms."""
import csv, json
from datetime import date
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; P=ROOT/'data/processed/v0.1.0-preview'; RAW=ROOT/'data/raw/public'; REG=ROOT/'metadata/source_recovery_register.csv'; OUT=ROOT/'metadata/observation_comparability_audit.csv'; DOC=ROOT/'docs/observation_comparability_audit.md'
def read(p):
    with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def main():
    reg={r['source_record_id']:r for r in read(REG)}; mr=read(RAW/'market_observations_raw.csv'); dr=read(RAW/'dc_observations_raw.csv'); cfg=json.loads((ROOT/'config/baseline.json').read_text(encoding='utf-8')); rows=[]; ref=date(2026,7,10)
    lows={'C04':3310,'M09':3240,'M11':3190}; highs={'C04':3370,'M09':3290,'M11':3290}; brands={'C06':'Zhongtian','M14':'Anhui Changjiang'}
    for r in mr:
        rid='PRICE_'+r['market_id']; d=date.fromisoformat(r['price_date']) if r['price_date'] else None; offset=(d-ref).days if d else ''
        form='geographic_proxy' if r['price_status']=='derived_proxy' else ('range_midpoint' if 'range' in r['price_status'] else 'direct_point'); spec=r['price_specification']; grade='HRB400E' if 'HRB400E' in spec else ''; diam=spec.replace('HRB400E ','') if grade else spec; status=reg[rid]['verification_status']; quality=reg[rid]['source_quality']; brand=brands.get(r['market_id'],'')
        if form=='geographic_proxy' or not d or (offset != '' and abs(offset)>30): level='low'
        elif '18-22' in spec: level='moderate'
        elif abs(offset)<=7: level='high'
        else: level='moderate'
        reason='geographic proxy; not a direct city quotation' if form=='geographic_proxy' else ('range midpoint; date/specification window supports only moderate comparison' if form=='range_midpoint' and level=='moderate' else ('date is more than 30 days from 2026-07-10' if level=='low' else ('specification band includes Phi20 rather than exact Phi20' if '18-22' in spec else 'same grade/specification and date within comparison window')))
        rows.append({'source_record_id':rid,'market_id':r['market_id'],'dc_id':'','city':r['city'],'observation_date_or_period':r['price_date'],'product':'Rebar','grade':grade,'diameter_or_specification':diam,'brand_or_mill':brand,'observation_form':form,'original_low':lows.get(r['market_id'],r['screening_price_cny_per_tonne'] if form=='direct_point' else ''),'original_high':highs.get(r['market_id'],r['screening_price_cny_per_tonne'] if form=='direct_point' else ''),'recovered_value':r['screening_price_cny_per_tonne'],'value_unit':'CNY/t','verification_status':status,'source_quality':quality,'date_offset_from_reference':offset,'comparable_to_reference':level,'comparability_reason':reason})
    rent_form={'C02':'specific_listing','C07':'high_standard_specific_listing'}; daily={'C03':0.75,'C04':0.66,'C05':0.70,'C06':0.74,'C08':0.50};
    for r in dr:
        rid='RENT_'+r['dc_id']; did=r['dc_id']; form=rent_form.get(did,'city_average'); period=r['observation_period']; basis='daily' if did in daily else 'monthly'; conv='daily x 30' if did in daily else 'monthly observed'; status=reg[rid]['verification_status']; quality=reg[rid]['source_quality'];
        if form!='city_average': level='low'; reason='specific listing; not a city average'
        elif did in ('C05','C06','C08') and status=='verified_exact': level='high'; reason='city average in July 2026 with exact verification'
        else: level='moderate'; reason='city average with Q1/Q2 timing or daily-to-monthly 30-day conversion'
        rows.append({'source_record_id':rid,'market_id':'','dc_id':did,'city':r['city'],'observation_date_or_period':period,'product':'','grade':'','diameter_or_specification':'','brand_or_mill':'','observation_form':form,'original_low':'','original_high':'','recovered_value':r['warehouse_rent_cny_per_sqm_month'],'value_unit':'CNY/m2/month','verification_status':status,'source_quality':quality,'date_offset_from_reference':'','comparable_to_reference':level,'comparability_reason':reason,'daily_or_monthly_basis':basis,'conversion_rule':conv})
    fields=['source_record_id','market_id','dc_id','city','observation_date_or_period','product','grade','diameter_or_specification','brand_or_mill','observation_form','original_low','original_high','recovered_value','value_unit','verification_status','source_quality','date_offset_from_reference','comparable_to_reference','comparability_reason','daily_or_monthly_basis','conversion_rule']
    with OUT.open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)
    pr=[x for x in rows if x['source_record_id'].startswith('PRICE_')]; rr=[x for x in rows if x['source_record_id'].startswith('RENT_')]; dates=[date.fromisoformat(x['observation_date_or_period']) for x in pr if x['observation_date_or_period']]; levels=lambda xs:{k:sum(x['comparable_to_reference']==k for x in xs) for k in ('high','moderate','low')}
    lines=['# Observation comparability audit','','Offline analysis only; original dates, values, URLs, and processed data are unchanged.','',f"PRICE records: {len(pr)}; comparability counts: {levels(pr)}",f"RENT records: {len(rr)}; comparability counts: {levels(rr)}",f"PRICE date range: {min(dates)} to {max(dates)} (span {(max(dates)-min(dates)).days} days)",f"PRICE records >7 days from 2026-07-10: {', '.join(x['source_record_id'] for x in pr if x['date_offset_from_reference']!='' and abs(int(x['date_offset_from_reference']))>7)}",f"PRICE records >30 days from 2026-07-10: {', '.join(x['source_record_id'] for x in pr if x['date_offset_from_reference']!='' and abs(int(x['date_offset_from_reference']))>30)}",'','Range midpoint records: PRICE_C04, PRICE_M09, PRICE_M11.','Geographic proxy: PRICE_M15.','Brand-specific: PRICE_C06 (Zhongtian); PRICE_M14 (Anhui Changjiang).','Specification-band record: PRICE_M13 (HRB400E Phi18-22).','Specific rent listings: RENT_C02 and RENT_C07.','Daily-to-monthly rent conversions: RENT_C03, RENT_C04, RENT_C05, RENT_C06, RENT_C08 (daily x 30).','', '## Appropriate uses','', 'The data support a regional network research case, public-data calibration, screening parameterization of city heterogeneity, and robustness/sensitivity experiments.','They should not be described as a strict same-day cross-sectional steel-price panel, fully same-brand/same-specification transaction prices, uniformly defined warehouse transaction rents, or enterprise actual operating costs.','', '## Future version strategies','', '**A: freeze v0.1.0-preview** and disclose screening/calibration limits without rerunning experiments.','**B: build v0.2-candidate** with a common steel-price date/window, HRB400E Phi20, explicit brand policy, and uniform city-average quarterly rents; preserve v0.1.0-preview, regenerate processed/lineage, and rerun downstream experiments. No strategy is selected or implemented in this audit.']
    DOC.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(json.dumps({'price_records':len(pr),'rent_records':len(rr),'rows':len(rows)}))
if __name__=='__main__':main()
